import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"First Mission","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/first-mission.md","filePath":"tutorials/first-mission.md","lastUpdated":null}'),r={name:"tutorials/first-mission.md"};function o(n,e,l,h,d,c){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="first-mission" tabindex="-1">First Mission <a class="header-anchor" href="#first-mission" aria-label="Permalink to &quot;First Mission&quot;">​</a></h1><p>Step-by-step walkthrough of your first ASTRA mission.</p><h2 id="_1-launch-astra" tabindex="-1">1. Launch ASTRA <a class="header-anchor" href="#_1-launch-astra" aria-label="Permalink to &quot;1. Launch ASTRA&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop.py</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The application opens with the <strong>Home</strong> perspective showing headline stats.</p><h2 id="_2-navigate-to-operations" tabindex="-1">2. Navigate to Operations <a class="header-anchor" href="#_2-navigate-to-operations" aria-label="Permalink to &quot;2. Navigate to Operations&quot;">​</a></h2><p>Click <strong>Operations</strong> in the toolbar (or press the Operations button). You&#39;ll see the mission configuration panel.</p><h2 id="_3-configure-the-mission" tabindex="-1">3. Configure the mission <a class="header-anchor" href="#_3-configure-the-mission" aria-label="Permalink to &quot;3. Configure the mission&quot;">​</a></h2><ul><li><strong>Receiver A</strong>: SmartScan (adaptive) — our proposed scheduler</li><li><strong>Receiver B</strong>: Sequential sweep — the conventional baseline</li><li><strong>Team size</strong>: 1 (single receiver per side)</li><li><strong>Sensitivity</strong>: 6.0 dB (default)</li></ul><h2 id="_4-start-the-mission" tabindex="-1">4. Start the mission <a class="header-anchor" href="#_4-start-the-mission" aria-label="Permalink to &quot;4. Start the mission&quot;">​</a></h2><p>Click <strong>▶ Start Mission</strong> (or press <code>F5</code>).</p><p>Two waterfall displays appear side by side. Each shows:</p><ul><li><strong>Blue-grey cells</strong>: True emitter transmissions (ground truth)</li><li><strong>Bright column</strong>: Where the receiver is currently tuned</li><li><strong>Amber markers</strong>: Confirmed intercepts</li></ul><h2 id="_5-watch-and-learn" tabindex="-1">5. Watch and learn <a class="header-anchor" href="#_5-watch-and-learn" aria-label="Permalink to &quot;5. Watch and learn&quot;">​</a></h2><p>Observe how SmartScan (left) behaves differently from the sequential sweep (right):</p><ul><li>SmartScan quickly identifies productive bands and returns to them</li><li>The sequential sweep blindly cycles through all bands regardless of content</li><li>After ~300 slots, SmartScan begins phase-locking on periodic emitters</li></ul><h2 id="_6-read-the-results" tabindex="-1">6. Read the results <a class="header-anchor" href="#_6-read-the-results" aria-label="Permalink to &quot;6. Read the results&quot;">​</a></h2><p>KPI counters below each waterfall update continuously:</p><ul><li><strong>Threat coverage</strong>: % of hostile emitters found at least once</li><li><strong>Reward per dwell</strong>: Average value earned per listen</li><li><strong>Hit rate</strong>: % of dwells that produced detections</li><li><strong>Prediction accuracy</strong>: % of correct ON/OFF predictions</li></ul><h2 id="_7-episode-completion" tabindex="-1">7. Episode completion <a class="header-anchor" href="#_7-episode-completion" aria-label="Permalink to &quot;7. Episode completion&quot;">​</a></h2><p>When the episode completes (slot 2400/2400), a result line shows the A/B comparison. The next episode starts automatically on a fresh scenario.</p><h2 id="_8-try-different-configurations" tabindex="-1">8. Try different configurations <a class="header-anchor" href="#_8-try-different-configurations" aria-label="Permalink to &quot;8. Try different configurations&quot;">​</a></h2><ul><li>Change Receiver B to <strong>UCB bandit</strong> to see the exploit trap</li><li>Increase <strong>Team size</strong> to 2 or 3 for cooperative scanning</li><li>Try <strong>Open scenario</strong> (File → Open scenario) for different battlefields</li><li>Adjust <strong>Rate</strong> to speed up or slow down the simulation</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/tutorials/connecting-hardware">Connecting Hardware</a> — wire in real SDR data</li><li><a href="/tutorials/training-models">Training Models</a> — train and save schedulers</li><li><a href="/tutorials/geolocation">Geolocation</a> — multi-receiver triangulation</li></ul>',25)])])}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
